page.script:
// 触发事件
function CrrHandler(t) {
	// 保存&更新事件
	if (t.id == "save") {
		var formpanel = Ext.getCmp("deliveryPlaceForm").getForm();
		if (formpanel.isValidCux()) {
			var gridpanel = Ext.getCmp("deliveryPlaceDepotList");
			var gridpanelData = gridpanel.getStore().getData();
			if (gridpanel.operateArray.length === 0 && gridpanelData.length === 0) {
				Ext.MessageBox.alert("提示", "请选择仓库档案");
				return false;
			}
			var data = formpanel.getValues();
			data.depotNos = gridpanel.operateArray.map(obj => obj.data.depotNo).join(',');
			var url = "/webapi/archives/deliveryPlace/add";
			if (data.id != null && data.id != "") {
				url = "/webapi/archives/deliveryPlace/edit";
			}
			post(url, data, function(res) {
				Ext.MessageBox.alert("提示", res.msg);
				Ext.getCmp('deliveryPlaceList').getStore().load();
				Ext.getCmp('deliveryPlaceFormWin').close();
			});
		}
	}
	// 【仓库档案】新增事件
	if (t.id == "dpdNew") {
		var panel = Ext.getCmp('deliveryPlaceDepotList');
		var notIdList = getArrayAttribute(panel, 'id');
		var items = panel.getStore().getData().items;
		if (items.length > 0) {
			notIdList += "," + items.map(obj => obj.data.depotId).join(',');
		}
		var data = {
			confirm: "depotConfirm", 
			param: "notIdList: '" + notIdList + "' "
		};
		handleRoute("ChooseDepot", data);
	}
	// 【仓库档案】删除事件
	if (t.id == "dpdDelete") {
		var records = Ext.getCmp("deliveryPlaceDepotList").getSelectionModel().getSelection();
		if (records.length < 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行删除!");
			return false;
		}
		handleDelConfirm("/webapi/archives/deliveryPlace/depot/delete", records, Ext.getCmp("deliveryPlaceDepotList"));
	}
}
// 提货地分类列表
function chooseDeliveryPlaceClass() {
	var data = {confirm: "deliveryPlaceClassConfirm"};
	handleRoute("ChooseDeliveryPlaceClass", data);
}
// 提货地分类确定事件
function deliveryPlaceClassConfirm(data) {
	var form = Ext.getCmp("deliveryPlaceForm").getForm();
	form.findField("deliveryPlaceClassNo").setValue(data.deliveryPlaceClassNo);
	form.findField("deliveryPlaceClassName").setValue(data.deliveryPlaceClassName);
}
// 仓库档案确认事件
function depotConfirm(data) {
	setArrayData(Ext.getCmp('deliveryPlaceDepotList'), data);
	Ext.getCmp('deliveryPlaceDepotList').getStore().load();
}
// 重写加载事件
Ext.getCmp('deliveryPlaceDepotList').getStore().on('load', function(store) {
	var panel = Ext.getCmp('deliveryPlaceDepotList');
	store.add(panel.operateArray);
	panel.down('pagingtoolbarcustom').updatePagingInfo(store.getCount(), store.pageSize);
});
